export default function MysteryQuiz({ userId, onExit }: { userId: string | null; onExit: () => void }) {
  const [quota,setQuota]=useState({remaining:0,limit:3,loading:true,isAdmin:false,isSubscribed:false});
  const [question,setQuestion]=useState<Question|null>(null);
  const [feedback,setFeedback]=useState<string|null>(null);
  const [answered,setAnswered]=useState(false);
  const [busy,setBusy]=useState(false);
  const [message,setMessage]=useState("");
  const [session,setSession]=useState("");
  const [used,setUsed]=useState<number[]>([]);
  const timer=useRef<number|null>(null);
  const loadQuota=useCallback(async()=>{
    const response=await fetch("/api/game-access",{cache:"no-store"});
    const data=await response.json();
    if(!response.ok)throw new Error(data.error||"Quota unavailable");
    const privileged=Boolean(data.isAdmin||data.isSubscribed);
    const snapshot={remaining:Number(privileged?data.remainingByType?.["mystery-quiz"]??0:data.remainingBySection?.["mystery-quiz"]??0),limit:privileged?10:3,loading:false,isAdmin:Boolean(data.isAdmin),isSubscribed:Boolean(data.isSubscribed)};setQuota(snapshot);return snapshot;
  },[]);
  const reserveNext=useCallback(async()=>{
    if(!userId||busy)return;
    setBusy(true);setFeedback(null);setAnswered(false);setMessage("");
    try{
      const currentQuota=await loadQuota();
      if(currentQuota.remaining<=0){setQuestion(null);setMessage(currentQuota.isAdmin||currentQuota.isSubscribed?"Your quota for this section today has been exhausted. Please visit tomorrow to play again.":"Your free quota for this section has been exhausted. Please subscribe to enjoy further.");return;}
      const candidates=QUESTIONS.filter(q=>!used.includes(q.id));
      const pool=candidates.length?candidates:QUESTIONS;
      let selected:Question|null=null;
      let nextUsed=[...used];
      for(const candidate of [...pool].sort(()=>Math.random()-.5)){
        const reservationSessionId="mystery-"+Date.now()+"-"+Math.random().toString(36).slice(2);
        const response=await fetch("/api/game-access",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({sectionId:"mystery-quiz",gameTypeId:"mystery-quiz",challengeId:"mystery-q-"+candidate.id,challengeQuestion:candidate.question,reserveQuestion:true,reservationSessionId})});
        const data=await response.json();
        if(response.ok&&data.reserved){selected=candidate;setSession(reservationSessionId);nextUsed=[...nextUsed,candidate.id];break;}
        if(!data.repeated){if(response.status===403){setMessage(data.freeTrialsExhausted ? "Your free quota for this section has been exhausted. Please subscribe to enjoy further." : "Your quota for this section today has been exhausted. Please visit tomorrow to play again.");}else{setMessage(data.error||"Unable to load the next question.");}break;}
        nextUsed=[...nextUsed,candidate.id];
      }
      setUsed(nextUsed);
      if(selected){setQuestion(selected);await loadQuota();}
      else if(!message)setMessage("You have completed the available questions in this round.");
    }catch(error){setMessage(error instanceof Error?error.message:"Unable to load Mystery Quiz.");}
    finally{setBusy(false);}
  },[userId,busy,used,loadQuota,message]);
  useEffect(()=>{void reserveNext();return()=>{if(timer.current!==null)window.clearTimeout(timer.current);};},[]);
  const answer=async(index:number)=>{
    if(!question||answered||busy)return;
    setBusy(true);
    try{
      const response=await fetch("/api/game-access",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({sectionId:"mystery-quiz",gameTypeId:"mystery-quiz",challengeId:"mystery-q-"+question.id,challengeQuestion:question.question,reservationSessionId:session})});
      const data=await response.json();
      if(!response.ok){setMessage(data.freeTrialsExhausted?"Your free quota for this section has been exhausted. Please subscribe to enjoy further.":"Your quota for this section today has been exhausted. Please visit tomorrow to play again.");setQuestion(null);await loadQuota();return;}
      setQuota(current=>({...current,remaining:Number(current.isAdmin||current.isSubscribed?data.remaining??0:data.sectionRemaining??0)}));
      setAnswered(true);
      const correct=index===question.answer;
      if(correct){setFeedback("Correct! 🎉 "+question.explanation);const audio=new Audio("/correct.mp3");audio.volume=.85;void audio.play().catch(()=>{});timer.current=window.setTimeout(()=>void reserveNext(),5000);}
      else{setFeedback("No !! The correct answer is ("+question.options[question.answer]+")");const audio=new Audio("/Lose.mp3");audio.volume=.85;void audio.play().catch(()=>{});}
    }catch(error){setMessage(error instanceof Error?error.message:"Could not submit your answer.");}
    finally{setBusy(false);}
  };
  return <><div className="mx-auto w-full max-w-3xl rounded-3xl border border-violet-200 bg-gradient-to-br from-white via-violet-50 to-indigo-100 p-4 shadow-xl sm:p-6">
    <div className="rounded-2xl bg-gradient-to-r from-violet-700 via-indigo-700 to-blue-800 p-4 text-center text-white shadow-lg">
      <div className="text-3xl">🔎</div><h3 className="mt-1 text-2xl font-black">Mystery Quiz</h3>
      <p className="mt-1 text-xs font-bold text-violet-100">{quota.loading?"Checking quota…":quota.isAdmin||quota.isSubscribed?formatFreeQuotaLabel(quota.remaining, true, "quiz"):formatFreeQuotaLabel(quota.remaining, false, "quiz")}</p>
    </div>
    {question?<div className="mt-5">
      <div className="mb-3 flex items-center justify-between text-xs font-black text-violet-900"><span>CASE FILE #{String(question.id).padStart(2,"0")}</span><span>{used.length} / {QUESTIONS.length}</span></div>
      <div className="rounded-2xl border border-violet-200 bg-white p-4 text-sm font-semibold leading-7 text-slate-800 shadow-sm sm:p-5">{question.question}</div>
      <div className="mt-4 grid gap-3">{question.options.map((option,index)=><button key={index} type="button" disabled={answered||busy} onClick={()=>void answer(index)} className="flex min-h-14 items-start gap-3 rounded-xl border-2 border-violet-200 bg-white p-3 text-left text-sm font-bold text-slate-800 shadow-sm transition hover:border-indigo-500 hover:bg-indigo-50 disabled:cursor-default disabled:opacity-80"><span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-gradient-to-br from-violet-600 to-indigo-700 text-xs font-black text-white">{String.fromCharCode(65+index)}</span><span className="pt-0.5">{option}</span></button>)}</div>
      {feedback&&<div role="status" aria-live="polite" className="mt-4 rounded-xl border border-amber-300 bg-amber-50 p-4 text-center text-sm font-black leading-6 text-slate-900">{feedback}</div>}
      {answered&&!feedback?.startsWith("Correct!")&&<button type="button" onClick={()=>void reserveNext()} disabled={busy} className="mt-4 min-h-12 w-full rounded-full bg-gradient-to-r from-violet-700 to-indigo-700 px-5 py-3 text-sm font-black text-white shadow-lg disabled:opacity-60">Next question →</button>}
    </div>:<div className="mt-5 rounded-2xl border border-violet-200 bg-white p-6 text-center"><p className="font-bold text-slate-700">{busy?"Preparing your next case…":message||"Loading Mystery Quiz…"}</p></div>}
    <div className="mt-5 flex justify-center"><button type="button" onClick={onExit} className="rounded-full border border-violet-300 bg-white px-5 py-2.5 text-sm font-black text-violet-800 shadow-sm">← Back to Quiz World</button></div>
  </div><GameQuotaPopup open={!quota.loading && quota.remaining<=0} isPrivileged={quota.isAdmin||quota.isSubscribed} resetKey="mystery-quiz" /></>;
}